{
  "findings": [
    {
      "check_id": "CKV_AZURE_229",
      "title": "Ensure the Azure SQL Database Namespace is zone redundant",
      "resource": "azurerm_mssql_database.main",
      "severity": "MEDIUM",
      "explanation": "The database is not configured to be zone redundant. This increases the risk of downtime in case of a failure in a single availability zone."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"main\" {\n  name           = \"${var.project_name}-database\"\n  server_id      = azurerm_mssql_server.main.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 20\n  sku_name       = \"S0\"\n  zone_redundant = true\n  tags = var.common_tags\n}",
  "fix_summary": "Added the 'zone_redundant = true' property to ensure the database is zone redundant, reducing the risk of downtime in case of an availability zone failure."
}
